def test_rank_invoice_bracket_and_fallback():
    tiers = [(0.0, 0.1), (63.0, 0.2)]
    assert rank_invoice(150.0, tiers) == 28.5

def test_merge_order_quantity_minimum():
    assert merge_order({"id": "o1", "quantity": 2}) == []
    assert merge_order({"id": "o1", "quantity": 1}) == ["quantity below minimum: 1"]

def test_annotate_sku_bracket_and_fallback():
    tiers = [(0.0, 0.1), (18.0, 0.2)]
    assert annotate_sku(50.0, tiers) == 11.0

def test_audit_route_quantity_minimum():
    assert audit_route({"id": "r1", "quantity": 4}) == []
    assert audit_route({"id": "r1", "quantity": 3}) == ["quantity below minimum: 3"]

def test_dispatch_warehouse_truncation_cap():
    groups = [[{"id": f"e{i}", "arrived_at": "2024-01-01"} for i in range(150)]]
    assert len(dispatch_warehouse(groups)) == 144

def test_adjust_ledger_head_threshold():
    entries = [{"status": "a", "quantity": 53}, {"status": "b", "quantity": 10}]
    assert adjust_ledger(entries) == {"a": 53, "b": 10}
    entries = [{"status": "a", "quantity": 52}, {"status": "b", "quantity": 10}]
    assert adjust_ledger(entries) == {"a": 52}

def test_drain_sku_quantity_minimum():
    assert drain_sku({"id": "s1", "quantity": 4}) == []
    assert drain_sku({"id": "s1", "quantity": 3}) == ["quantity below minimum: 3"]

